// Generates the English, Chinese and Korean pages from the Japanese index.html.
//
// index.html (Japanese) is the source. Every Japanese text segment in it is looked up
// in i18n/<lang>.json ({ "日本語の文": "translation" }) and replaced.
// The blocks between <!-- i18n:... --> markers are generated by this script.
//
// Usage:
//   node scripts/build-i18n.js          generate pages
//   node scripts/build-i18n.js --list   print the Japanese segments that need translations
const fs = require('fs');
const path = require('path');

const SITE_URL = 'https://www0532-grilli.pages.dev';

// The first entry is the source language and is served from the site root.
const languages = [
  { code: 'ja', htmlLang: 'ja', dir: '', label: '日本語', short: 'JA', fonts: 'family=Noto+Sans+JP:wght@400;700&family=Noto+Serif+JP:wght@400;700' },
  { code: 'en', htmlLang: 'en', dir: 'en', label: 'English', short: 'EN', fonts: '' },
  { code: 'zh', htmlLang: 'zh-Hans', dir: 'zh', label: '简体中文', short: '中文', fonts: 'family=Noto+Sans+SC:wght@400;700&family=Noto+Serif+SC:wght@400;700' },
  { code: 'ko', htmlLang: 'ko', dir: 'ko', label: '한국어', short: '한국어', fonts: 'family=Noto+Sans+KR:wght@400;700&family=Noto+Serif+KR:wght@400;700' },
];

const switcherLabel = { ja: '言語を選択', en: 'Select language', zh: '选择语言', ko: '언어 선택' };

const root = path.join(__dirname, '..');
const sourceFile = path.join(root, 'index.html');
const [source] = languages;

// Hiragana, katakana, CJK ideographs, CJK symbols (〒, 〜, 、, 。) and full-width forms (：, （）)
const JAPANESE = /[\u3000-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uff00-\uffef]/;
const TRANSLATABLE_ATTRS = ['alt', 'placeholder', 'content', 'title', 'aria-label'];

const pageUrl = (lang) => `${SITE_URL}/${lang.dir ? `${lang.dir}/` : ''}`;

const renderHead = (lang) => [
  `  <link rel="canonical" href="${pageUrl(lang)}">`,
  `  <link rel="alternate" hreflang="x-default" href="${pageUrl(source)}">`,
  ...languages.map((l) => `  <link rel="alternate" hreflang="${l.htmlLang}" href="${pageUrl(l)}">`),
].join('\n');

const renderSwitcher = (lang) => {
  const rootPrefix = lang.dir ? '../' : './';
  const links = languages.map((l) => {
    const href = rootPrefix + (l.dir ? `${l.dir}/` : '');
    const current = l === lang ? ' aria-current="page"' : '';
    return `          <li><a href="${href}" class="lang-link" hreflang="${l.htmlLang}" lang="${l.htmlLang}"${current}>${l.label}</a></li>`;
  }).join('\n');

  return `      <details class="lang-switch" data-lang-switch>
        <summary class="lang-current" aria-label="${switcherLabel[lang.code]}">
          <ion-icon name="globe-outline" aria-hidden="true"></ion-icon>
          <span class="span">${lang.short}</span>
          <ion-icon name="chevron-down" aria-hidden="true" class="lang-arrow"></ion-icon>
        </summary>
        <ul class="lang-list">
${links}
        </ul>
      </details>`;
};

const blocks = { head: renderHead, switcher: renderSwitcher };

const fillBlocks = (html, lang) => {
  for (const [name, render] of Object.entries(blocks)) {
    const pattern = new RegExp(`(<!-- i18n:${name} -->)[\\s\\S]*?(\\n[ \\t]*<!-- /i18n:${name} -->)`);
    if (!pattern.test(html)) throw new Error(`Marker <!-- i18n:${name} --> not found in index.html`);
    html = html.replace(pattern, (m, start, end) => `${start}\n${render(lang)}${end}`);
  }
  return html;
};

const emptyBlocks = (html) => html.replace(/(<!-- i18n:(\w+) -->)[\s\S]*?(\n[ \t]*<!-- \/i18n:\2 -->)/g, '$1$3');

// Calls fn(segment) for every Japanese text node and attribute value, and replaces it with the result.
const mapJapanese = (html, fn) => {
  const translateText = (text) => {
    const trimmed = text.trim();
    if (!JAPANESE.test(trimmed)) return text;
    const startIndex = text.indexOf(trimmed);
    return text.slice(0, startIndex) + fn(trimmed) + text.slice(startIndex + trimmed.length);
  };

  return html.replace(/<!--[\s\S]*?-->|<script[\s\S]*?<\/script>|<[^>]+>|[^<]+/g, (part) => {
    if (part.startsWith('<!--') || part.startsWith('<script')) return part;
    if (!part.startsWith('<')) return translateText(part);
    return part.replace(
      new RegExp(`(\\s(?:${TRANSLATABLE_ATTRS.join('|')})=")([^"]*)(")`, 'g'),
      (m, before, value, after) => before + translateText(value) + after,
    );
  });
};

const html = fs.readFileSync(sourceFile, 'utf8');
const base = emptyBlocks(html);

if (process.argv.includes('--list')) {
  const segments = new Set();
  mapJapanese(base, (s) => { segments.add(s); return s; });
  console.log(JSON.stringify(Object.fromEntries([...segments].map((s) => [s, ''])), null, 2));
  process.exit(0);
}

const errors = [];

for (const lang of languages) {
  let output;

  if (lang === source) {
    output = fillBlocks(html, lang);
  } else {
    const dict = JSON.parse(fs.readFileSync(path.join(root, 'i18n', `${lang.code}.json`), 'utf8'));

    output = mapJapanese(base, (segment) => {
      if (dict[segment]) return dict[segment];
      errors.push(`i18n/${lang.code}.json: missing translation for "${segment}"`);
      return segment;
    });

    if (!output.includes(source.fonts)) throw new Error('Google Fonts URL for Japanese not found in index.html');
    output = output
      .replace(/<html lang="[^"]*">/, `<html lang="${lang.htmlLang}">`)
      .replace(lang.fonts ? source.fonts : `&${source.fonts}`, lang.fonts)
      .replace(/(\s(?:src|href)=")\.\//g, '$1../')
      .replace(/url\('\.\//g, "url('../");
    output = fillBlocks(output, lang);
  }

  const outDir = path.join(root, lang.dir);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, 'index.html'), output);
  console.log(`Generated ${lang.dir ? `${lang.dir}/` : ''}index.html`);
}

if (errors.length) {
  console.error(`\n${[...new Set(errors)].join('\n')}`);
  process.exit(1);
}
